style.css:
body {
    font-family: Arial, sans-serif;
    background-color: #FFC5C5; /* light pink */
}

header {
    background-color: #FF69B4; /* hot pink */
    padding: 20px;
    text-align: center;
}

header img {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    margin: 20px auto;
}

nav ul {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    justify-content: space-between;
}

nav li {
    margin-right: 20px;
}

nav a {
    color: #FFFFFF;
    text-decoration: none;
}

main {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 20px;
}

section {
    background-color: #FFFFFF;
    padding: 20px;
    border: 1px solid #FFC5C5;
    border-radius: 10px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

h1, h2 {
    color: #FF69B4; /* hot pink */
}

button {
    background-color: #FF69B4; /* hot pink */
    color: #FFFFFF;
    border: none;
    padding: 10px 20px;
    border-radius: 10px;
    cursor: pointer;
}

button:hover {
    background-color: #FFC5C5; /* light pink */
}

footer {
    background-color: #FF69B4; /* hot pink */
    padding: 10px;
    text-align: center;
    color: #FFFFFF;
    clear: both;
}
